const test = require('node:test');
const assert = require('node:assert/strict');
const { EventEmitter } = require('node:events');
const { onceReady } = require('../ready.cjs');
test('cannot reenter through a synchronous emit', () => {
  const emitter = new EventEmitter();
  let calls = 0, outside = 0, receiver, seen;
  emitter.on('ready', () => outside++);
  onceReady(emitter, 'ready', function (...args) {
    receiver = this; seen = args; calls++;
    if (calls === 1) emitter.emit('ready', 'nested');
  });
  emitter.emit('ready', 'release8', 2);
  assert.equal(calls, 1);
  assert.strictEqual(receiver, emitter);
  assert.deepEqual(seen, ['release8',2]);
  assert.equal(outside, 2);
  assert.equal(emitter.listenerCount('ready'), 1);
});
test('throwing handler is already detached', () => {
  const emitter = new EventEmitter();
  const failure = new Error('deployment rejected');
  onceReady(emitter, 'ready', () => { throw failure; });
  assert.throws(() => emitter.emit('ready'), error => error === failure);
  assert.equal(emitter.listenerCount('ready'), 0);
  assert.doesNotThrow(() => emitter.emit('ready'));
});
test('cancellation before delivery', () => {
  const emitter = new EventEmitter();
  let calls = 0;
  const stop = onceReady(emitter, 'ready', () => calls++);
  stop(); stop(); emitter.emit('ready');
  assert.equal(calls, 0);
});

test('earlier listener reemission cannot deliver the once handler twice', () => {
  const emitter = new EventEmitter();
  let nested = false, calls = 0;
  emitter.on('deployed', () => {
    if (!nested) { nested = true; emitter.emit('deployed', 'nested'); }
  });
  onceReady(emitter, 'deployed', function (value) {
    calls++;
    assert.strictEqual(this, emitter);
    assert.equal(value, 'nested');
  });
  emitter.emit('deployed', 'outer');
  assert.equal(calls, 1);
  assert.equal(emitter.listenerCount('deployed'), 1);
});

