function onceReady(emitter, topic, handler) {
  let fired = false;
  function wrapped(...args) {
    if (fired) return;
    fired = true;
    emitter.off(topic, wrapped);
    handler.apply(emitter, args);
  }
  emitter.on(topic, wrapped);
  return () => emitter.off(topic, wrapped);
}
module.exports = { onceReady };

